// ===============================
// 2x1 Multiplexer
// ===============================
module mux2x1 (
    input wire a,
    input wire b,
    input wire sel,
    output wire y
);
    assign y = sel ? b : a;
endmodule


// ===============================
// 16x1 Multiplexer (structural)
// built ONLY from 2x1 MUXes
// ===============================
module mux16x1 (
    input wire [15:0] d,
    input wire [3:0] sel,
    output wire y
);

    wire [7:0] w1;
    wire [3:0] w2;
    wire [1:0] w3;

    // Level 1: 16 -> 8
    mux2x1 m0  (d[0],  d[1],  sel[0], w1[0]);
    mux2x1 m1  (d[2],  d[3],  sel[0], w1[1]);
    mux2x1 m2  (d[4],  d[5],  sel[0], w1[2]);
    mux2x1 m3  (d[6],  d[7],  sel[0], w1[3]);
    mux2x1 m4  (d[8],  d[9],  sel[0], w1[4]);
    mux2x1 m5  (d[10], d[11], sel[0], w1[5]);
    mux2x1 m6  (d[12], d[13], sel[0], w1[6]);
    mux2x1 m7  (d[14], d[15], sel[0], w1[7]);

    // Level 2: 8 -> 4
    mux2x1 m8  (w1[0], w1[1], sel[1], w2[0]);
    mux2x1 m9  (w1[2], w1[3], sel[1], w2[1]);
    mux2x1 m10 (w1[4], w1[5], sel[1], w2[2]);
    mux2x1 m11 (w1[6], w1[7], sel[1], w2[3]);

    // Level 3: 4 -> 2
    mux2x1 m12 (w2[0], w2[1], sel[2], w3[0]);
    mux2x1 m13 (w2[2], w2[3], sel[2], w3[1]);

    // Level 4: 2 -> 1
    mux2x1 m14 (w3[0], w3[1], sel[3], y);

endmodule


// ===============================
// Testbench
// ===============================
module tb_mux16x1;

    reg  [15:0] d;
    reg  [3:0]  sel;
    wire        y;

    mux16x1 DUT (
        .d(d),
        .sel(sel),
        .y(y)
    );

    initial begin
        // ---- Waveform dump (Deliverable 3) ----
        $dumpfile("dump.vcd");
        $dumpvars(0, tb_mux16x1);

        // ---- Console output (Deliverable 2) ----
        $monitor("Time=%0t | sel=%b | d=%b | y=%b",
                  $time, sel, d, y);

        // Test data
        d = 16'b1010_1100_1111_0001;

        // Sweep all select values
        sel = 4'b0000; #10;
        sel = 4'b0001; #10;
        sel = 4'b0010; #10;
        sel = 4'b0011; #10;
        sel = 4'b0100; #10;
        sel = 4'b0101; #10;
        sel = 4'b0110; #10;
        sel = 4'b0111; #10;
        sel = 4'b1000; #10;
        sel = 4'b1001; #10;
        sel = 4'b1010; #10;
        sel = 4'b1011; #10;
        sel = 4'b1100; #10;
        sel = 4'b1101; #10;
        sel = 4'b1110; #10;
        sel = 4'b1111; #10;

        $finish;
    end

endmodule

